    {
        "name": "Erysipelas",
        "name_ja": "豚丹毒",
        "symptoms": {"fever", "diamond_skin_lesions", "lameness", "joint_swelling", "lethargy", "anorexia", "sudden_death"},
        "description": "Erysipelas is a clinical condition requiring veterinary evaluation, diagnosis, and appropriate treatment.",
        "description_ja": "豚丹毒菌による細菌感染で特徴的な菱形皮膚病変、関節炎、致死的敗血症を引き起こす。",
        "urgency": "emergency",
        "recommended_tests": ["血液培養", "細菌培養", "血液検査", "関節液検査"],
        "causes": "Infection with Erysipelothrix rhusiopathiae through wound contamination, ingestion, or inhalation. Stress, immunosuppression, and overcrowding are predisposing factors.",
        "causes_ja": "Exotic Otherにおける丹毒（Exotic Other）の原因: 創傷汚染、経口摂取、吸入、日和見的過剰増殖による細菌コロニー形成。ストレス、免疫抑制、不衛生、過密飼育、併発疾患が素因となる。",
        "pathophysiology": "The pathological process involves tissue injury, inflammatory response, and progressive functional impairment. Without intervention, compensatory mechanisms may be overwhelmed, leading to clinical deterioration.",
        "pathophysiology_ja": "丹毒（Exotic Other）はExotic Otherにおける細菌感染症である。病原菌は付着因子を通じて組織にコロニーを形成し、毒素産生、酵素分泌、免疫回避戦略などの病原性メカニズムを介して侵入する。好中球浸潤、サイトカイン放出、補体活性化を含む炎症カスケードが生じる。組織損傷は細菌の直接作用と宿主の炎症反応の両方に起因する。菌種と宿主の免疫状態に応じて、膿瘍形成、敗血症、または慢性肉芽腫性炎症が発生しうる。",
        "treatment": "Penicillin G 20,000-40,000 IU/kg IM q12-24h x 7-10d. SC/IV fluids. Zoonotic. Isolate.",
        "treatment_ja": "Exotic Otherにおける丹毒（Exotic Other）の治療には、可能であれば培養感受性試験に基づく標的抗菌薬療法が必要である。結果待ちの間は経験的広域抗菌薬を開始する。抗菌薬治療期間は感染の排除と耐性予防に十分な期間とする。膿瘍や壊死組織には外科的排膿またはデブリードマンが必要な場合がある。支持療法として輸液、鎮痛薬、抗炎症薬、栄養サポートを行う。",
        "prevention": "適切な飼育管理、バランスの取れた栄養、定期的な獣医師による健康診断、ストレス軽減、初期症状の早期治療が予防に重要である。",
        "prevention_ja": "丹毒（Exotic Other）の予防には適切な衛生管理・消毒、利用可能なワクチン接種、創傷の迅速な処置、ストレス軽減、適切な換気、感染動物の隔離が含まれる。",
        "prognosis": "予後は重症度、基礎疾患、治療の時期に依存する。早期の積極的介入により転帰が改善する。治療の遅延は予後慎重〜不良となる。",
        "prognosis_ja": "豚丹毒の予後: 早期治療で多くは良好。定期モニタリングで管理可能。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "young", "senior"},
    },
