    {
        "name": "Gastrointestinal Stasis",
        "name_ja": "消化管うっ滞",
        "symptoms": {"anorexia", "bloating", "constipation", "lethargy", "teeth_grinding", "abdominal_pain"},
        "description": "Gastrointestinal Stasis is a gastrointestinal condition affecting digestive function and nutrient absorption.",
        "description_ja": "ストレス、疼痛、食事、脱水による消化管運動の低下または停止。",
        "urgency": "high",
        "recommended_tests": ["腹部X線検査", "身体検査", "血液検査"],
        "causes": "Reduced or absent GI motility from stress, pain, diet, or dehydration; common across exotic mammals.",
        "causes_ja": "Exotic Otherにおける消化管うっ滞の原因: ストレス、疼痛、食事、脱水による消化管運動の低下または停止。",
        "pathophysiology": "Gastrointestinal Stasis is a nutritional disorder in Exotic Other. Reduced or absent GI motility from stress, pain, diet, or dehydration; common across exotic mammals. The condition results from inadequate intake, malabsorption, or excessive supplementation of specific nutrients. Deficiency states impair biochemical pathways dependent on the affected nutrient as cofactor or substrate, leading to cellular dysfunction. Excess states cause toxicity through accumulation in tissues or disruption of nutrient interactions. Species-specific dietary requirements make proper nutritional management critical for prevention.",
        "pathophysiology_ja": "消化管うっ滞はExotic Otherにおける栄養障害である。特定の栄養素の不十分な摂取、吸収不良、または過剰摂取により生じる。欠乏状態では、影響を受けた栄養素を補因子または基質として必要とする生化学的経路が障害され、細胞機能障害を引き起こす。過剰状態では組織への蓄積や栄養素間相互作用の障害により毒性が生じる。種特異的な食事要求により、適切な栄養管理が予防に不可欠である。",
        "treatment": "Treatment of gastrointestinal stasis in exotic other centers on correcting the nutritional imbalance. Deficiency states require supplementation of the specific nutrient through dietary correction or therapeutic supplementation. Excess states require dietary restriction and supportive care for organ damage. Gradual correction prevents refeeding syndrome in malnourished animals. Species-specific dietary requirements must guide long-term nutritional planning. Regular reassessment ensures adequate without excessive intake.",
        "treatment_ja": "Exotic Otherにおける消化管うっ滞の治療は栄養バランスの是正が中心となる。欠乏状態では食事の改善または治療的サプリメンテーションにより特定の栄養素を補充する。過剰状態では食事制限と臓器障害に対する支持療法を行う。栄養不良動物ではリフィーディング症候群予防のため段階的に是正する。種特異的な食事要求に基づく長期栄養計画を立案する。過不足のない摂取を確保するため定期的に再評価する。",
        "prevention": "適切な飼育管理、バランスの取れた栄養、定期的な獣医師による健康診断、ストレス軽減、初期症状の早期治療が予防に重要である。",
        "prevention_ja": "消化管うっ滞の予防には全ての栄養要求を満たす種に適した食事設計、単一食品のみの食事の回避、獣医師との定期的な食事内容の見直し、必要時の適切なサプリメンテーション、種固有の栄養ニーズに関する知識が必要である。",
        "prognosis": "予後は疾患の重症度、治療介入の時期、治療への反応に依存する。早期診断と適切な治療により転帰が改善する。",
        "prognosis_ja": "消化管うっ滞の予後: 急性は多くが良好。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "young", "senior"},
    },
