    {
        "name": "Tusk Problems (Mini Pig)",
        "name_ja": "牙の問題（ミニブタ）",
        "symptoms": {"tusk_overgrowth", "tusk_abscess", "mouth_pain", "difficulty_eating", "facial_swelling", "aggression"},
        "description": "Tusk Problems (Mini Pig) is a clinical condition requiring veterinary evaluation, diagnosis, and appropriate treatment.",
        "description_ja": "未去勢の雄ミニブタにおける牙の過成長、破折、または膿瘍。疼痛と感染リスクを伴う。",
        "urgency": "moderate",
        "recommended_tests": ["口腔内検査", "頭部X線検査", "鎮静下検査"],
        "causes": "Overgrown, fractured, or abscessed tusks in intact male mini pigs causing pain and infection risk.",
        "causes_ja": "Exotic Otherにおける牙の問題（ミニブタ）の原因: 未去勢の雄ミニブタにおける牙の過成長、破折、または膿瘍。疼痛と感染リスクを伴う。",
        "pathophysiology": "Overgrown, fractured, or abscessed tusks in intact male mini pigs causing pain and infection risk. Pathogenic bacteria colonize tissues through adhesion factors and invade via virulence mechanisms including toxin production, enzyme secretion, and immune evasion strategies. The resulting inflammatory cascade involves neutrophil infiltration, cytokine release, and complement activation. Tissue damage results from both direct bacterial action and the host's inflammatory response. Abscess formation, septicemia, or chronic granulomatous inflammation may develop depending on the organism and host immune status.",
        "pathophysiology_ja": "牙の問題（ミニブタ）はExotic Otherにおける細菌感染症である。病原菌は付着因子を通じて組織にコロニーを形成し、毒素産生、酵素分泌、免疫回避戦略などの病原性メカニズムを介して侵入する。好中球浸潤、サイトカイン放出、補体活性化を含む炎症カスケードが生じる。組織損傷は細菌の直接作用と宿主の炎症反応の両方に起因する。菌種と宿主の免疫状態に応じて、膿瘍形成、敗血症、または慢性肉芽腫性炎症が発生しうる。",
        "treatment": "Appropriate treatment based on specific diagnosis, supportive care, dietary optimization, environmental management, and regular follow-up monitoring.",
        "treatment_ja": "Exotic Otherにおける牙の問題（ミニブタ）の治療には、可能であれば培養感受性試験に基づく標的抗菌薬療法が必要である。結果待ちの間は経験的広域抗菌薬を開始する。抗菌薬治療期間は感染の排除と耐性予防に十分な期間とする。膿瘍や壊死組織には外科的排膿またはデブリードマンが必要な場合がある。支持療法として輸液、鎮痛薬、抗炎症薬、栄養サポートを行う。",
        "prevention": "予防には、適切な衛生管理、利用可能なワクチン接種、外傷の早期治療、ストレス軽減、適切な換気、感染動物の隔離が重要である。",
        "prevention_ja": "牙の問題（ミニブタ）の予防には適切な衛生管理・消毒、利用可能なワクチン接種、創傷の迅速な処置、ストレス軽減、適切な換気、感染動物の隔離が含まれる。",
        "prognosis": "Generally good to fair with appropriate treatment and follow-up care. Prognosis improves with early diagnosis and owner compliance.",
        "prognosis_ja": "牙の問題（ミニブタ）の予後: 早期治療で多くは良好。定期モニタリングで管理可能。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "young", "senior"},
    },
