    {
        "name": "Caprine Arthritis Encephalitis (CAE)",
        "name_ja": "ヤギ関節炎脳炎（CAE）",
        "symptoms": {"joint_swelling", "lameness", "mastitis", "neurological_signs", "weight_loss"},
        "description": "Caprine Arthritis Encephalitis (CAE) is a clinical condition requiring veterinary evaluation, diagnosis, and appropriate treatment.",
        "description_ja": "ヤギに慢性関節炎・脳炎・乳房炎を引き起こすレンチウイルス。",
        "urgency": "high",
        "recommended_tests": ["serology_ELISA", "PCR_CAE", "synovial_fluid_analysis"],
        "causes": "Lentivirus causing chronic arthritis, encephalitis, and mastitis in goats.",
        "causes_ja": "Exotic Otherにおけるヤギ関節炎脳炎（CAE）の原因: ヤギに慢性関節炎・脳炎・乳房炎を引き起こすレンチウイルス。",
        "pathophysiology": "Caprine Arthritis Encephalitis (CAE) is caused by viral infection in Exotic Other. Lentivirus causing chronic arthritis, encephalitis, and mastitis in goats. The virus enters host cells through specific receptor-mediated mechanisms, hijacking cellular machinery for replication. This leads to direct cytopathic effects including cell lysis, apoptosis, and tissue necrosis in target organs. The host immune response—involving both innate (interferons, NK cells) and adaptive (antibody, cell-mediated) pathways—may contribute to immunopathology. Viremia can disseminate the pathogen to multiple organ systems, and immunosuppression may predispose to secondary bacterial or fungal infections.",
        "pathophysiology_ja": "ヤギ関節炎脳炎（CAE）はExotic Otherにおけるウイルス感染症である。ウイルスは特定の受容体を介して宿主細胞に侵入し、細胞内機構を利用して複製する。直接的な細胞変性効果（細胞溶解、アポトーシス、標的臓器の組織壊死）を引き起こす。自然免疫（インターフェロン、NK細胞）および適応免疫（抗体、細胞性免疫）の宿主免疫応答が免疫病理に寄与することがある。ウイルス血症により病原体が複数の臓器系に播種される可能性があり、免疫抑制により二次的な細菌・真菌感染のリスクが高まる。",
        "treatment": "Treatment of caprine arthritis encephalitis (cae) in exotic other is primarily supportive, as most viral infections lack specific antiviral therapy. Fluid therapy maintains hydration and corrects electrolyte imbalances. Antipyretics and analgesics manage fever and discomfort. Broad-spectrum antibiotics prevent or treat secondary bacterial infections. Nutritional support—including assisted feeding if anorexic—is essential. Immunostimulants or interferons may be beneficial in some cases. Isolation of affected individuals prevents transmission to susceptible contacts.",
        "treatment_ja": "Exotic Otherにおけるヤギ関節炎脳炎（CAE）の治療は主に支持療法であり、多くのウイルス感染症には特異的抗ウイルス薬がない。輸液療法により水分補給と電解質補正を行う。解熱鎮痛薬で発熱と不快感を管理する。広域抗菌薬で二次細菌感染を予防・治療する。食欲不振時の補助給餌を含む栄養サポートが不可欠である。免疫賦活剤やインターフェロンが有効な場合がある。感受性個体への伝播防止のため罹患個体を隔離する。",
        "prevention": "適切な飼育管理、バランスの取れた栄養、定期的な獣医師による健康診断、ストレス軽減、初期症状の早期治療が予防に重要である。",
        "prevention_ja": "ヤギ関節炎脳炎（CAE）の予防にはワクチン接種（利用可能な場合）、新規・病気動物の隔離、厳格なバイオセキュリティ対策、適切な消毒プロトコル、既知のキャリアや汚染環境との接触回避が含まれる。",
        "prognosis": "予後は疾患の重症度、治療介入の時期、治療への反応に依存する。早期診断と適切な治療により転帰が改善する。",
        "prognosis_ja": "ヤギ関節炎脳炎（CAE）の予後: 早期治療で多くは良好。定期モニタリングで管理可能。",
        "onset_pattern": {"acute", "chronic", "subacute"},
        "age_predisposition": {"adult", "senior"},
    },
